"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type ScrollRevealPrimitiveProps = ComponentProps<typeof motion.div>;

export function ScrollRevealPrimitive({ children, ...props }: ScrollRevealPrimitiveProps) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : { opacity: 0, y: 28 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.2 }}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.26, ease: [0.23, 1, 0.32, 1] }}
    >
      {children}
    </motion.div>
  );
}
